DROP TABLE IF EXISTS `ingredient_conflict`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ingredient_conflict` (
  `conflict_id` bigint NOT NULL AUTO_INCREMENT,
  `ingredient1_id` bigint NOT NULL,
  `ingredient2_id` bigint NOT NULL,
  `ingredient1_name` varchar(100) DEFAULT NULL,
  `ingredient2_name` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`conflict_id`),
  UNIQUE KEY `uq_conflict_pair` (`ingredient1_id`,`ingredient2_id`),
  KEY `idx_conflict_ing1` (`ingredient1_id`),
  KEY `idx_conflict_ing2` (`ingredient2_id`),
  CONSTRAINT `fk_conflict_ing1` FOREIGN KEY (`ingredient1_id`) REFERENCES `ingredient` (`ingredient_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_conflict_ing2` FOREIGN KEY (`ingredient2_id`) REFERENCES `ingredient` (`ingredient_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8155 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

