--
-- Table structure for table `product`
--

DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `product_id` bigint NOT NULL,
  `brand_name` varchar(50) DEFAULT NULL,
  `brand_name_kor` varchar(50) DEFAULT NULL,
  `product_name` varchar(100) DEFAULT NULL,
  `product_name_kor` varchar(100) DEFAULT NULL,
  `category` varchar(30) DEFAULT NULL,
  `function` varchar(20) DEFAULT NULL,
  `ranking` int DEFAULT NULL,
  `price` int DEFAULT NULL,
  `sim_1` bigint DEFAULT NULL,
  `sim_2` bigint DEFAULT NULL,
  `sim_3` bigint DEFAULT NULL,
  `sim_4` bigint DEFAULT NULL,
  PRIMARY KEY (`product_id`),
  KEY `idx_product_category` (`category`),
  KEY `idx_product_ranking` (`ranking`),
  KEY `idx_product_sim_1` (`sim_1`),
  KEY `idx_product_sim_2` (`sim_2`),
  KEY `idx_product_sim_3` (`sim_3`),
  KEY `idx_product_sim_4` (`sim_4`),
  CONSTRAINT `fk_product_sim_1` FOREIGN KEY (`sim_1`) REFERENCES `product` (`product_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_product_sim_2` FOREIGN KEY (`sim_2`) REFERENCES `product` (`product_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_product_sim_3` FOREIGN KEY (`sim_3`) REFERENCES `product` (`product_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_product_sim_4` FOREIGN KEY (`sim_4`) REFERENCES `product` (`product_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

