--
-- Table structure for table `product_ingredient`
--

DROP TABLE IF EXISTS `product_ingredient`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_ingredient` (
  `product_ingredient_id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `ingredient_id` bigint NOT NULL,
  `inci_brand` varchar(100) DEFAULT NULL,
  `inci_product_name` varchar(100) DEFAULT NULL,
  `function` varchar(200) DEFAULT NULL,
  `image_url` text,
  PRIMARY KEY (`product_ingredient_id`),
  UNIQUE KEY `uq_pi_product_ingredient` (`product_id`,`ingredient_id`),
  KEY `idx_pi_product_id` (`product_id`),
  KEY `idx_pi_ingredient_id` (`ingredient_id`),
  CONSTRAINT `fk_pi_ingredient` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredient` (`ingredient_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pi_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`product_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36788 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

