CREATE TABLE `product_review` (
  `review_id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `pro1` varchar(50) DEFAULT NULL,
  `pro2` varchar(50) DEFAULT NULL,
  `pro3` varchar(50) DEFAULT NULL,
  `pro4` varchar(50) DEFAULT NULL,
  `pro5` varchar(50) DEFAULT NULL,
  `pro6` varchar(50) DEFAULT NULL,
  `pro7` varchar(50) DEFAULT NULL,
  `con1` varchar(50) DEFAULT NULL,
  `con2` varchar(50) DEFAULT NULL,
  `con3` varchar(50) DEFAULT NULL,
  `con4` varchar(50) DEFAULT NULL,
  `con5` varchar(50) DEFAULT NULL,
  `con6` varchar(50) DEFAULT NULL,
  `con7` varchar(50) DEFAULT NULL,
  `pros_text` text,
  `cons_text` text,
  PRIMARY KEY (`review_id`),
  UNIQUE KEY `uq_product_review_product_id` (`product_id`),
  CONSTRAINT `fk_product_review_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`product_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1450 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
